def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def merge_status(name: str, status: str) -> None:
        # precedence: fail > skip > pass
        if not name:
            return
        current = results.get(name)
        if current == "fail":
            return
        if status == "fail":
            results[name] = "fail"
            return
        if status == "skip":
            if current != "fail":
                results[name] = "skip"
            return
        if current is None:
            results[name] = "pass"

    def testcase_status(testcase: ET.Element) -> str:
        if testcase.find("failure") is not None or testcase.find("error") is not None:
            return "fail"
        if testcase.find("skipped") is not None:
            return "skip"
        status_attr = (testcase.get("status") or "").lower()
        if status_attr in {"notrun", "skipped", "skip"}:
            return "skip"
        return "pass"

    def handle_xml_root(root: ET.Element) -> None:
        for testcase in root.findall(".//testcase"):
            classname = testcase.get("classname") or ""
            name = testcase.get("name") or ""
            if classname and name:
                full_name = f"{classname}.{name}"
            else:
                full_name = classname or name
            merge_status(full_name, testcase_status(testcase))

    # 1) Try full XML parse
    try:
        root = ET.fromstring(log.strip())
        handle_xml_root(root)
    except ET.ParseError:
        pass

    # 2) Extract XML blocks and parse individually
    xml_pattern = re.compile(
        r'(<\?xml[^>]*\?>\s*)?(<testsuite\b[\s\S]*?</testsuite>|<testsuites\b[\s\S]*?</testsuites>)',
        re.IGNORECASE,
    )
    for match in xml_pattern.finditer(log):
        xml_block = match.group(0)
        try:
            root = ET.fromstring(xml_block.strip())
        except ET.ParseError:
            # regex fallback for malformed xml block
            for tc_match in re.finditer(
                r'<testcase\b([^>]*)>([\s\S]*?)</testcase>|<testcase\b([^>]*)/?>',
                xml_block,
                re.IGNORECASE,
            ):
                attrs_text = tc_match.group(1) or tc_match.group(3) or ""
                body = tc_match.group(2) or ""
                attrs = dict(re.findall(r'(\w+)="([^"]*)"', attrs_text))
                classname = attrs.get("classname", "")
                name = attrs.get("name", "")
                full_name = f"{classname}.{name}" if classname and name else (classname or name)
                status = "pass"
                if re.search(r"<failure\b|<error\b", body, re.IGNORECASE):
                    status = "fail"
                elif re.search(r"<skipped\b", body, re.IGNORECASE):
                    status = "skip"
                else:
                    status_attr = (attrs.get("status") or "").lower()
                    if status_attr in {"notrun", "skipped", "skip"}:
                        status = "skip"
                merge_status(full_name, status)
            continue
        handle_xml_root(root)

    # 3) Line-based fallbacks (pytest/unittest/go/jest)
    for line in log.splitlines():
        line = line.strip()
        # pytest
        m = re.match(r'(.+::.+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b', line)
        if m:
            status = m.group(2).lower()
            merge_status(m.group(1), "fail" if status in {"failed", "error"} else ("skip" if status == "skipped" else "pass"))
            continue
        # unittest
        m = re.match(r'(\w+\.\w+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b', line, re.IGNORECASE)
        if m:
            status = m.group(2).lower()
            merge_status(m.group(1), "fail" if status in {"fail", "error"} else ("skip" if status == "skipped" else "pass"))
            continue
        # go test
        m = re.match(r'---\s+(PASS|FAIL|SKIP):\s+(\S+)', line)
        if m:
            status = m.group(1).lower()
            merge_status(m.group(2), "fail" if status == "fail" else ("skip" if status == "skip" else "pass"))
            continue
        # jest-style
        m = re.match(r'(PASS|FAIL)\s+(.+)', line)
        if m:
            status = m.group(1).lower()
            merge_status(m.group(2).strip(), "fail" if status == "fail" else "pass")
            continue
        if line.startswith("✓ "):
            merge_status(line[2:].strip(), "pass")
        elif line.startswith("✕ "):
            merge_status(line[2:].strip(), "fail")
        elif line.startswith("○ "):
            merge_status(line[2:].strip(), "skip")

    return results
